// Package: Microsoft.Extensions.Caching.StackExchangeRedis
// Install: dotnet add package Microsoft.Extensions.Caching.StackExchangeRedis

using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Caching.StackExchangeRedis;
using System.Text.Json;

public class PostService
{
    private readonly BlogContext _db;
    private readonly IDistributedCache _cache;
    private readonly ILogger<PostService> _logger;

    public PostService(BlogContext db, IDistributedCache cache, ILogger<PostService> logger)
    {
        _db = db;
        _cache = cache;
        _logger = logger;
    }

    public async Task<List<Post>> GetTopPostsAsync(CancellationToken ct = default)
    {
        const string cacheKey = "top-posts";
        try
        {
            var cached = await _cache.GetStringAsync(cacheKey, ct);
            if (cached is not null)
            {
                _logger.LogInformation("Returning top posts from cache");
                return JsonSerializer.Deserialize<List<Post>>(cached)!;
            }

            var posts = await _db.Posts
                .OrderByDescending(p => p.PublishedAt)
                .Take(10)
                .ToListAsync(ct);

            var json = JsonSerializer.Serialize(posts);
            await _cache.SetStringAsync(cacheKey, json, new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
            }, ct);

            _logger.LogInformation("Cached {Count} top posts", posts.Count);
            return posts;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Cache read failed, falling back to database");
            // Fallback to database on cache failure
            return await _db.Posts.OrderByDescending(p => p.PublishedAt).Take(10).ToListAsync(ct);
        }
    }
}

